// @pit: {"label": "Add addendum and custom preamble support to builtin extension"}
async ({ workspace: { read, edit } }) => {
  const f = await read("src/builtin-extension.ts", { format: "raw" });
  let c = f.content;
  const rep = (a: string, b: string) => { if (!c.includes(a)) throw new Error("missing: " + a.slice(0, 60)); c = c.replace(a, b); };
  rep(`/** The section keys of the built-in extension, in order, for \`wrapSection\`. */
export const BUILTIN_SECTIONS = [
	"preamble",
	"tools",
	"rules",
	PROJECT_CONTEXT_SECTION,`, `/**
 * The section keys of the built-in extension, in order, for \`wrapSection\`. With a \`SYSTEM.md\`, \`tools\` and \`rules\`
 * are not there (see \`createBuiltinExtension\`).
 */
export const BUILTIN_SECTIONS = [
	"preamble",
	"tools",
	"rules",
	"addendum",
	PROJECT_CONTEXT_SECTION,`);
  rep(`	/** The run's skills, listed in the \`available_skills\` section. */
	skills: Skills;
}`, `	/** The run's skills, listed in the \`available_skills\` section. */
	skills: Skills;
	/** \`SYSTEM.md\` (see system-prompt-files.ts): replaces the \`preamble\`, \`tools\`, and \`rules\` sections. */
	systemPrompt?: string | undefined;
	/** \`APPEND_SYSTEM.md\`: the \`addendum\` section, after \`rules\`; none when undefined. */
	appendSystemPrompt?: string | undefined;
}`);
  rep(` * so their wraps (\`wrapSection("rules", ...)\`) apply to it.
 */`, ` * so their wraps (\`wrapSection("rules", ...)\`) apply to it. A \`SYSTEM.md\` replaces pi's own sections (\`preamble\`,
 * \`tools\`, \`rules\`) with one untagged \`preamble\` that has its text, as pi's \`customPrompt\`; the others stay.
 */`);
  rep(`	const sections: PromptSection[] = [
		section("preamble", () => PREAMBLE, { tag: false }),
		section("tools", (input) => formatToolsSection(input.agent.tools)),
		section("rules", (input) => formatRulesSection(input.agent.tools)),
		section(PROJECT_CONTEXT_SECTION`, `	const { systemPrompt, appendSystemPrompt } = options;
	const base: PromptSection[] =
		systemPrompt === undefined
			? [
					section("preamble", () => PREAMBLE, { tag: false }),
					section("tools", (input) => formatToolsSection(input.agent.tools)),
					section("rules", (input) => formatRulesSection(input.agent.tools)),
				]
			: [section("preamble", () => systemPrompt, { tag: false })];
	const sections: PromptSection[] = [
		...base,
		section("addendum", () => appendSystemPrompt),
		section(PROJECT_CONTEXT_SECTION`);
  await edit("src/builtin-extension.ts", { revision: f.revision, changes: [{ kind: "replaceFile", content: c }] });
